class Solution {
public:
    int mod=1e9+7;
    int solve(int m,int n,int maxmoves,int x,int y,vector<vector<vector<int>>> &dp,int moves)
    {
        if(x>=m or y>=n or y<0 or x<0)
            return 1;
        if(moves==maxmoves)
            return 0;
        if(dp[moves][x][y]!=-1)
            return dp[moves][x][y]%mod;
        int temp=0;
        temp=(temp+solve(m,n,maxmoves,x+1,y,dp,moves+1))%mod;
        temp=(temp+solve(m,n,maxmoves,x,y+1,dp,moves+1))%mod;
        temp=(temp+solve(m,n,maxmoves,x-1,y,dp,moves+1))%mod;
        temp=(temp+solve(m,n,maxmoves,x,y-1,dp,moves+1))%mod;
        dp[moves][x][y]=temp%mod;
        return dp[moves][x][y];
    }
    int findPaths(int m, int n, int maxmoves, int startRow, int startColumn) {
        vector<vector<vector<int>>> dp(maxmoves+1,vector<vector<int>> (m+1,vector<int> (n+1,-1)));
        dp[maxmoves][m][n]=solve(m,n,maxmoves,startRow,startColumn,dp,0);
        return dp[maxmoves][m][n];
    }
};

# Dynamic Programming
class Solution(object):
    def findPaths(self, m, n, maxMove, startRow, startColumn):
        """
        :type m: int
        :type n: int
        :type maxMove: int
        :type startRow: int
        :type startColumn: int
        :rtype: int
        """
        ans = 0
        mod = 10 ** 9 + 7
        cur_dp = [[0 for _ in range(n)] for _ in range(m)]
        cur_dp[startRow][startColumn] = 1
        for _ in range(maxMove):
            for i in range(n):
                ans = (ans + cur_dp[0][i] + cur_dp[m - 1][i]) % mod
            for i in range(m):
                ans = (ans + cur_dp[i][0] + cur_dp[i][n - 1]) % mod
            new_dp = [[0 for _ in range(n)] for _ in range(m)]
            for i in range(m):
                for j in range(n):
                    if i - 1 >= 0:
                        new_dp[i][j] += cur_dp[i - 1][j]
                    if i + 1 < m:
                        new_dp[i][j] += cur_dp[i + 1][j]
                    if j - 1 >= 0:
                        new_dp[i][j] += cur_dp[i][j - 1]
                    if j + 1 < n:
                        new_dp[i][j] += cur_dp[i][j + 1]
            for i in range(m):
                for j in range(n):
                    cur_dp[i][j] = new_dp[i][j]
        return ans
